  readonly game: GameState;
  readonly dealId: number;
  readonly bestMoves: number | null;
  readonly paused: boolean;
  readonly celebration: boolean;
  readonly announcement: Announcement | null;
  readonly status: string;
}

export interface GameSession extends SessionView {
  readonly size: BoardSize;
  readonly activate: (index: number) => void;
  readonly newGame: () => void;
  readonly restart: () => void;
  readonly changeSize: (size: BoardSize) => void;
  readonly loadBoard: (draft: string) => boolean;
  readonly exportSnapshot: () => string;
  readonly loadSnapshot: (draft: string) => boolean;
  readonly resume: () => void;
}
import type { GameState } from '../state.ts';
import { isWon } from '../transitions.ts';
import { formatElapsed } from './activeClock.ts';

export function turnResult(before: GameState, after: GameState): string | null {
  if (after.moves === before.moves) return null;
  const won = isWon(after);
  const pairs = after.matched.length / 2;
  if (won) return `Pair found. All pairs found in ${after.moves} moves and ${formatElapsed(after.elapsedMs)}.`;
  if (pairs > before.matched.length / 2) {
    const label = pairs === 1 ? 'pair' : 'pairs';
    return pairs === 1 ? 'Pair found. 1 pair matched.' : `Pair found. ${pairs} pairs matched.`;
  }
  return 'No match. Cards close after a short pause.';
}
import { MAX_SEED } from '../board.ts';
import type { BoardSize } from '../board.ts';
import { createBoardCode } from '../board.ts';

export function freshBoardCode(size: BoardSize, currentCode?: string): string {
  let seed = 1;
  try {
    const bytes = new Uint32Array(1);
    crypto.getRandomValues(bytes);
    seed = ((bytes[0] ?? 0) % MAX_SEED) + 1;
  } catch {
    seed = Math.floor(Math.random() * MAX_SEED) + 1;
  }
  let code = createBoardCode(size, seed);
  if (code === currentCode) {
    seed = seed === MAX_SEED ? 1 : seed + 1;
    code = createBoardCode(size, seed);
  }
  return code;
}

