  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --page: #090B14;
  --panel: #141827;
  --back: #1B2034;
  --face: #111625;
  --text: #F4F6FF;
  --secondary: #B8BDD2;
  --border: #757C9A;
  --focus: #FFFFFF;
  --green: #8BEA7D;
  background: var(--page);
  color: var(--text);
  font-size: 16px;
  line-height: 24px;
}

* { box-sizing: border-box; }
html { min-width: 0; background: var(--page); }
body {
  min-width: 0;
  margin: 0;
  background: radial-gradient(ellipse at 85% -6%, rgb(99 231 255 / 8%), transparent 42rem), var(--page);
  color: var(--text);
  font-size: 16px;
  line-height: 24px;
}
button, input, textarea, select { font-family: inherit; }
.visually-hidden, .live-announcer {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.game-page {
  width: min(100%, 1120px);
  min-height: 100dvh;
  margin-inline: auto;
  padding: 32px 16px;
}

.game-header { margin-bottom: 24px; }
.eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  color: var(--secondary);
  font-size: 14px;
  letter-spacing: 0.12em;
}
.eyebrow-dot { width: 8px; height: 8px; border-radius: 50%; background: #63E7FF; box-shadow: 0 0 10px #63E7FF; }
h1 { margin: 0; font-size: 24px; line-height: 32px; font-weight: 720; letter-spacing: 0.01em; }
.intro { margin: 4px 0 0; color: var(--secondary); font-size: 14px; }

.score-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 16px;
}
.score-strip p {
  min-width: 0;
  margin: 0;
  padding: 8px 12px;
  border: 1px solid #30364D;
  border-radius: 8px;
  background: #111625;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.win-banner {
  margin: 0 0 16px;
  padding: 12px 16px;
  border: 1px solid #8BEA7D;
  border-radius: 10px;
  background: rgb(139 234 125 / 9%);
  color: var(--green);
  font-weight: 700;
  text-align: center;
}
.win-banner.is-new-win { animation: win-pulse 600ms ease-out 1; }
@keyframes win-pulse {
  0% { box-shadow: 0 0 0 rgb(139 234 125 / 0%); transform: scale(1); }
  36% { box-shadow: 0 0 28px rgb(139 234 125 / 32%); transform: scale(1.012); }
  100% { box-shadow: 0 0 0 rgb(139 234 125 / 0%); transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .win-banner.is-new-win { animation: none; }
}

@media (max-width: 520px) {
  .game-page { padding: 24px 16px; }
  .score-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .deal-controls { gap: 8px; }
  .size-control { flex-basis: 100%; }
}

@media (max-height: 520px) {
  .game-page { padding-block: 16px; }
  .game-header { margin-bottom: 12px; }
  .intro { display: none; }
}
.board-card {
  position: relative;
  display: grid;
  width: 100%;
  aspect-ratio: 1;
  place-items: center;
  padding: 2px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  cursor: pointer;
  transition: border-color 120ms ease;
  scroll-margin: 8px;
  -webkit-tap-highlight-color: transparent;
}

.board-card[data-state="revealed"], .board-card[data-state="matched"] {
  background: var(--face);
}

.board-card:not(.is-matched):hover { border-color: var(--text); }
.board-card.is-matched, .board-card.is-matched:hover { border-color: var(--green); }
.board-card:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; z-index: 1; }

.face-art, .card-back-art {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.matched-check {
  position: absolute;
  top: 2px;
  right: 3px;
  color: var(--green);
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
}

@media (prefers-reduced-motion: reduce) {
  .board-card { transition: none; }
}
