export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type BoardSize = (typeof BOARD_SIZES)[number];
export const MIN_SEED = 1;
export const MAX_SEED = 2_147_483_646;
const PARK_MILLER_MODULUS = 2_147_483_647;
const PARK_MILLER_MULTIPLIER = 16_807;
const RANDOM_RANGE = 2_147_483_646;

export interface Board {
  readonly code: string;
  readonly size: BoardSize;
  readonly seed: number;
  readonly deck: readonly number[];
}

export function isBoardSize(value: unknown): value is BoardSize {
  return typeof value === 'number' && BOARD_SIZES.some((size) => size === value);
}

function draw(state: { value: number }, bound: number): number {
  const limit = Math.floor(RANDOM_RANGE / bound) * bound;
  while (true) {
    state.value = (state.value * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
    const candidate = state.value - 1;
    if (candidate < limit) return candidate % bound;
  }
}

export function generateDeck(size: BoardSize, seed: number): readonly number[] {
  const cards = Array.from({ length: size * size }, (_, index) => Math.floor(index / 2));
  const random = { value: seed };
  for (let index = cards.length - 1; index > 0; index -= 1) {
    const other = draw(random, index + 1);
    const held = cards[index];
    const swapped = cards[other];
    if (held === undefined || swapped === undefined) throw new Error('Invalid shuffle index');
    cards[index] = swapped;
    cards[other] = held;
  }
  return Object.freeze(cards);
}

export function parseBoardCode(text: string): Board | null {
  const match = /^np1-([0-9]+)-([1-9][0-9]*)$/.exec(text);
  const sizeText = match?.[1];
  const seedText = match?.[2];
  if (sizeText === undefined || seedText === undefined) return null;
  const size = Number(sizeText);
  const seed = Number(seedText);
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed < MIN_SEED || seed > MAX_SEED) return null;
  return Object.freeze({ code: `np1-${size}-${seed}`, size, seed, deck: generateDeck(size, seed) });
}

export function createBoardCode(size: BoardSize, seed: number): string {
  if (!Number.isSafeInteger(seed) || seed < MIN_SEED || seed > MAX_SEED) throw new RangeError('Invalid board seed');
  return `np1-${size}-${seed}`;
}
import type { Board } from './board.ts';

export const MISMATCH_MS = 800;
export const MAX_MOVES = 999_999;
export const MAX_ELAPSED_MS = 359_999_999;

export interface ClosedSelection {
  readonly kind: 'closed';
}

export interface OneSelection {
  readonly kind: 'one';
  readonly index: number;
}

export interface MismatchSelection {
  readonly kind: 'mismatch';
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
}

export type Selection = ClosedSelection | OneSelection | MismatchSelection;

export interface GameState {
  readonly board: Board;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export const CLOSED_SELECTION: ClosedSelection = Object.freeze({ kind: 'closed' });

export function makeGameState(
  board: Board,
  matched: readonly number[] = [],
  selection: Selection = CLOSED_SELECTION,
  moves = 0,
  elapsedMs = 0,
  started = false
): GameState {
  return Object.freeze({
    board,
    matched: Object.freeze([...matched]),
    selection: Object.freeze({ ...selection }),
    moves,
    elapsedMs,
    started
  });
}
import { parseBoardCode } from './board.ts';
import type { GameState } from './state.ts';
import { makeGameState } from './state.ts';

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  return board === null ? null : makeGameState(board);
}
import { CLOSED_SELECTION, MAX_ELAPSED_MS, MAX_MOVES } from './state.ts';
import type { GameState } from './state.ts';
import { makeGameState } from './state.ts';

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isSafeInteger(index) || index < 0 || index >= state.board.deck.length || isWon(state)) return state;
  if (state.matched.includes(index) || state.selection.kind === 'mismatch') return state;
  if (state.selection.kind === 'closed') {
    return makeGameState(state.board, state.matched, { kind: 'one', index }, state.moves, state.elapsedMs, true);
  }
  if (state.selection.kind === 'one') {
    if (state.selection.index === index) return state;
    const nextMoves = Math.min(MAX_MOVES, state.moves + 1);
    const firstFace = state.board.deck[state.selection.index];
    const nextFace = state.board.deck[index];
    if (firstFace === nextFace) {
      return makeGameState(state.board, [...state.matched, state.selection.index, index], CLOSED_SELECTION, nextMoves, state.elapsedMs, true);
