import { forwardRef } from 'react';
import type { KeyboardEvent, MouseEvent } from 'react';
import { FACE_BACKGROUND, faceIdentity } from './faceIdentity.ts';

interface BoardCardProps {
  readonly faceId: number;
  readonly revealed: boolean;
  readonly matched: boolean;
  readonly row: number;
  readonly column: number;
  readonly tabStop: boolean;
  readonly onFocus: () => void;
  readonly onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
  readonly onActivate: () => void;
}

function HiddenBack() {
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 100" className="card-back-art">
      <path d="M50 28L72 50L50 72L28 50Z" fill="none" stroke="#757C9A" strokeWidth="4" />
    </svg>
  );
}

function CardView({ faceId, revealed, matched, row, column, tabStop, onFocus, onKeyDown, onActivate }: BoardCardProps, ref: React.ForwardedRef<HTMLButtonElement>) {
  const position = `Row ${row}, column ${column}`;
  const label = revealed
    ? `${position}, ${faceIdentity(faceId).name}, ${matched ? 'matched' : 'revealed'}`
    : `${position}, closed`;

  function activate(event: MouseEvent<HTMLButtonElement>): void {
    const native = event.nativeEvent;
    if (native.detail === 0 && (native.altKey || native.ctrlKey || native.metaKey || native.shiftKey)) return;
    onActivate();
  }

  return (
    <button
      ref={ref}
      type="button"
      className={`board-card${matched ? ' is-matched' : ''}`}
      data-state={matched ? 'matched' : revealed ? 'revealed' : 'closed'}
      aria-label={label}
      aria-disabled={matched ? 'true' : undefined}
      tabIndex={tabStop ? 0 : -1}
      onFocus={onFocus}
      onKeyDown={onKeyDown}
      onClick={activate}
    >
      {revealed ? <FaceShape id={faceId} /> : <HiddenBack />}
      {matched ? <span className="matched-check" aria-hidden="true">✓</span> : null}
    </button>
  );
}

function FaceShape({ id }: { readonly id: number }) {
  const face = faceIdentity(id);
  const diagonal = 28.284;
  const marker: Record<string, readonly [number, number]> = {
    top: [50, 10], 'top-right': [50 + diagonal, 50 - diagonal], right: [90, 50],
    'bottom-right': [50 + diagonal, 50 + diagonal], bottom: [50, 90],
    'bottom-left': [50 - diagonal, 50 + diagonal], left: [10, 50], 'top-left': [50 - diagonal, 50 - diagonal]
  };
  const [x, y] = marker[face.marker] ?? [50, 10];
  const circle = face.shape === 'circle';
  const paths: Record<string, string> = {
    square: 'M26 26H74V74H26Z', triangle: 'M50 26L74 72H26Z', diamond: 'M50 26L74 50L50 74L26 50Z',
    star: 'M50 26L56 43L74 43L59 54L65 72L50 61L35 72L41 54L26 43L44 43Z',
    hexagon: 'M38 26H62L74 50L62 74H38L26 50Z',
    plus: 'M42 26H58V42H74V58H58V74H42V58H26V42H42Z',
    chevron: 'M30 28L70 50L30 72V58L45 50L30 42Z'
  };
  const shapeProps = face.fill === 'solid'
    ? { fill: face.color }
    : { fill: 'none', stroke: face.color, strokeWidth: 5 };
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 100" className="card-face-art">
      {circle ? <circle cx="50" cy="50" r="24" {...shapeProps} />
        : <path d={paths[face.shape] ?? paths.square} strokeLinejoin="round" {...shapeProps} />}
      <circle cx={x} cy={y} r="5" fill={face.color} stroke={FACE_BACKGROUND} strokeWidth="3" />
    </svg>
  );
}

export const BoardCard = forwardRef(CardView);

