.board-card {
  position: relative;
  display: grid;
  width: 100%;
  aspect-ratio: 1;
  place-items: center;
  padding: 6px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  cursor: pointer;
  transition: border-color 120ms ease;
  scroll-margin: 8px;
  -webkit-tap-highlight-color: transparent;
}

.board-card[data-state="revealed"], .board-card[data-state="matched"] {
  background: var(--face);
}

.board-card:not(.is-matched):hover { border-color: var(--text); }
.board-card.is-matched, .board-card.is-matched:hover { border-color: var(--green); }
.board-card:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; z-index: 1; }

.card-face-art, .card-back-art {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.matched-check {
  position: absolute;
  top: 2px;
  right: 3px;
  color: var(--green);
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
}

@media (prefers-reduced-motion: reduce) {
  .board-card { transition: none; }
}

