import { useRef } from 'react';
import { Board } from './game/board/Board.tsx';
import type { BoardFocusHandle } from './game/board/Board.tsx';
import { DealControls } from './game/controls/DealControls.tsx';
import { ReproductionControls } from './game/controls/ReproductionControls.tsx';
import { formatElapsed } from './game/session/activeClock.ts';
import { useGameSession } from './game/session/useGameSession.ts';
import './styles.css';

export function Game() {
  const session = useGameSession();
  const boardRef = useRef<BoardFocusHandle>(null);
  const pairs = session.game.matched.length / 2;
  const totalPairs = session.game.board.deck.length / 2;
  const won = pairs === totalPairs;

  function resumeGame(): void {
    boardRef.current?.focusRemembered();
    session.resume();
  }

  return (
    <main className="game-page">
      <header className="game-header">
        <p className="eyebrow"><span className="eyebrow-dot" aria-hidden="true" /> MEMORY GAME</p>
        <h1>Neon Pairs</h1>
        <p className="intro">Find the matching faces. Remember each one as you go.</p>
      </header>

      <DealControls
        size={session.size}
        onSizeChange={session.changeSize}
        onNewGame={session.newGame}
        onRestart={session.restart}
      />

      <section className="score-strip" aria-label="Game status">
        <p><span className="score-label">Moves:</span> {session.game.moves}</p>
        <p><span className="score-label">Pairs:</span> {pairs}/{totalPairs}</p>
        <p><span className="score-label">Time:</span> {formatElapsed(session.game.elapsedMs)}</p>
        <p><span className="score-label">Best:</span> {session.bestMoves === null ? 'none' : session.bestMoves}</p>
      </section>

      {won ? (
        <p className={`win-banner${session.celebration ? ' is-new-win' : ''}`}>
          Board cleared <span aria-hidden="true">·</span> {session.game.moves} moves <span aria-hidden="true">·</span> {formatElapsed(session.game.elapsedMs)}
        </p>
      ) : null}

      <div className="live-announcer" aria-live="polite" aria-atomic="true">
        <span key={session.announcement?.id ?? 'empty'}>{session.announcement?.text ?? ''}</span>
      </div>

      <Board
        key={session.dealId}
        ref={boardRef}
        game={session.game}
        paused={session.paused}
        onActivate={session.activate}
      />

      <ReproductionControls session={{ ...session, resume: resumeGame }} />
    </main>
  );
}
import { forwardRef } from 'react';
import type { FocusEvent, ForwardedRef, KeyboardEvent, MouseEvent } from 'react';
import { FaceArt } from './FaceArt.tsx';
import { faceIdentity } from './faceIdentity.ts';

interface BoardCardProps {
  readonly faceId: number;
  readonly revealed: boolean;
  readonly matched: boolean;
  readonly row: number;
  readonly column: number;
  readonly tabStop: boolean;
  readonly onFocus: (event: FocusEvent<HTMLButtonElement>) => void;
  readonly onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
  readonly onActivate: () => void;
}

function HiddenBack() {
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 100" className="card-back-art">
      <path d="M50 28L72 50L50 72L28 50Z" fill="none" stroke="#757C9A" strokeWidth="4" />
    </svg>
  );
}

function CardView({ faceId, revealed, matched, row, column, tabStop, onFocus, onKeyDown, onActivate }: BoardCardProps, ref: ForwardedRef<HTMLButtonElement>) {
  const position = `Row ${row}, column ${column}`;
  const label = revealed
    ? `${position}, ${faceIdentity(faceId).name}, ${matched ? 'matched' : 'revealed'}`
    : `${position}, closed`;

  function activate(event: MouseEvent<HTMLButtonElement>): void {
    if (event.button !== 0) return;
    const native = event.nativeEvent;
    if (native.detail === 0 && (native.altKey || native.ctrlKey || native.metaKey || native.shiftKey)) return;
    onActivate();
  }

  return (
    <button
      ref={ref}
      type="button"
      className={`board-card${matched ? ' is-matched' : ''}`}
      data-state={matched ? 'matched' : revealed ? 'revealed' : 'closed'}
      aria-label={label}
      aria-disabled={matched ? 'true' : undefined}
      tabIndex={tabStop ? 0 : -1}
      onFocus={onFocus}
      onKeyDown={onKeyDown}
      onClick={activate}
    >
      {revealed ? <FaceArt id={faceId} /> : <HiddenBack />}
      {matched ? <span className="matched-check" aria-hidden="true">✓</span> : null}
    </button>
  );
}

export const BoardCard = forwardRef(CardView);
.board-card {
  position: relative;
  display: grid;
  width: 100%;
  aspect-ratio: 1;
  place-items: center;
  padding: 0;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  cursor: pointer;
  transition: border-color 120ms ease;
  scroll-margin: 8px;
  -webkit-tap-highlight-color: transparent;
}

.board-card[data-state="revealed"], .board-card[data-state="matched"] {
  background: var(--face);
}

.board-card:not(.is-matched):hover { border-color: var(--text); }
.board-card.is-matched, .board-card.is-matched:hover { border-color: var(--green); }
.board-card:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; z-index: 1; }

.face-art, .card-back-art {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
}

.matched-check {
  position: absolute;
  top: 4px;
  right: 4px;
  color: var(--green);
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
}

@media (prefers-reduced-motion: reduce) {
  .board-card { transition: none; }
